package com.andye.warmod.phalanx.client;import com.mojang.blaze3d.vertex.*;import net.minecraft.client.renderer.texture.OverlayTexture;
public final class PhalanxTurretMesh{private PhalanxTurretMesh(){}public static void render(PoseStack.Pose p,VertexConsumer b,int light,float yaw,float pitch,float spin){box(p,b,.15F,.72F,.15F,.85F,1.35F,.85F,82,91,96,light);float cy=1.30F;for(int i=0;i<6;i++){double a=i*Math.PI/3+spin;float y=cy+(float)Math.sin(a)*.12F,z=.50F+(float)Math.cos(a)*.12F;box(p,b,.45F,y-.035F,z-.035F,.55F,y+.035F,1.65F,45,51,54,light);}box(p,b,.24F,.05F,.24F,.76F,.72F,.76F,96,104,108,light);}private static void box(PoseStack.Pose p,VertexConsumer b,float x1,float y1,float z1,float x2,float y2,float z2,int r,int g,int bl,int l){quad(p,b,x1,y1,z1,x2,y1,z1,x2,y2,z1,x1,y2,z1,r,g,bl,l);quad(p,b,x2,y1,z2,x1,y1,z2,x1,y2,z2,x2,y2,z2,r,g,bl,l);quad(p,b,x1,y1,z2,x1,y1,z1,x1,y2,z1,x1,y2,z2,r,g,bl,l);quad(p,b,x2,y1,z1,x2,y1,z2,x2,y2,z2,x2,y2,z1,r,g,bl,l);}private static void quad(PoseStack.Pose p,VertexConsumer b,float ax,float ay,float az,float bx,float by,float bz,float cx,float cy,float cz,float dx,float dy,float dz,int r,int g,int bl,int l){v(p,b,ax,ay,az,r,g,bl,l);v(p,b,bx,by,bz,r,g,bl,l);v(p,b,cx,cy,cz,r,g,bl,l);v(p,b,dx,dy,dz,r,g,bl,l);}private static void v(PoseStack.Pose p,VertexConsumer b,float x,float y,float z,int r,int g,int bl,int l){b.addVertex(p,x,y,z).setColor(r,g,bl,255).setUv(0,0).setOverlay(OverlayTexture.NO_OVERLAY).setLight(l).setNormal(p,0,1,0);}}
